def get_endpoint_context(dependant: Dependant, route: APIRoute) -> Optional[str]:
    try:
        file = inspect.getfile(dependant.call)
        line = inspect.getsourcelines(dependant.call)[1]
        name = dependant.call.__name__
        method = list(route.methods)[0] if route.methods else ""
        path = route.path
        return f"File {file}, line {line}, in {name}\n    {method} {path}"
    except Exception:
        return None


